const departmentChannelMap = {
  'Engineering': ['all-testn8n', 'new-channel'],
  'Sales': ['all-testn8n', 'social'],
  'Marketing': ['all-testn8n', 'social'],
  'HR': ['all-testn8n', 'new-channel'],
  'Design': ['all-testn8n', 'social']
};

const dept = $input.first().json.department;
const channels = departmentChannelMap[dept] || ['all-testn8n'];

const SLACK_INVITE_LINK = 'https://join.slack.com/t/testn8n-6i17414/shared_invite/zt-429tad5xx-6dmoOUMbNCJ_TmQpYUrUzA';

return [{
  json: {
    ...$input.first().json,
    target_channels: channels,
    slack_invite_link: SLACK_INVITE_LINK
  }
}];

