const body = $input.first().json.body;
const user = body.event.user;

return [{
  json: {
    slack_user_id: user.id,
    email: user.profile.email,
    real_name: user.profile.real_name || user.real_name
  }
}];

const departmentChannelMap = {
  'Engineering': ['all-testn8n', 'new-channel'],
  'Sales': ['all-testn8n', 'social'],
  'Marketing': ['all-testn8n', 'social'],
  'HR': ['all-testn8n', 'new-channel'],
  'Design': ['all-testn8n', 'social']
};

const employee = $input.first().json;
const slackUser = $('Extract New User Info').first().json;
const channels = departmentChannelMap[employee.department] || ['all-testn8n'];

return [{
  json: {
    ...employee,
    slack_user_id: slackUser.slack_user_id,
    target_channels: channels
  }
}];

const channelName = $('Split Out Channels').first().json.target_channels.replace('#', '');
const channels = $input.first().json.channels;

const match = channels.find(c => c.name === channelName || c.name_normalized === channelName);

if (!match) {
  return [{
    json: {
      ...$('Split Out Channels').first().json,
      channel_id: null,
      error: `Channel '${channelName}' not found — check bot is in the channel and name matches exactly`
    }
  }];
}

return [{
  json: {
    ...$('Split Out Channels').first().json,
    channel_id: match.id
  }
}];

